import { describe, it, expect, beforeEach } from 'vitest';
import {
  EvidenceStore,
  EvidenceEntry,
  PrivacyRulesConfig,
  lintCitations,
  validateMetrics,
  redactText,
} from '../src/index';

describe('Integrity & Redaction Engine', () => {
  let store: EvidenceStore;

  const verifiedEntry: EvidenceEntry = {
    id: 'ev-001',
    date: '2026-01-15',
    company: 'acme-corp',
    title: 'Core Database Migration',
    summary: 'Migrated primary cluster from Mongo to Postgres.',
    impact: 'Reduced p99 latency by 45%.',
    themes: ['database', 'performance'],
    confidence: 'verified',
    in_flight: false,
    metrics: [
      { name: 'latency reduction', value: '45%', status: 'verified' },
    ],
    internal_references: [
      { type: 'jira', ref: 'DB-101' },
    ],
  };

  const provisionalEntry: EvidenceEntry = {
    id: 'ev-002',
    date: '2026-02-20',
    company: 'acme-corp',
    title: 'Distributed Caching Layer',
    summary: 'Introduced Redis caching for hot user profiles.',
    impact: 'Estimated 30% reduction in database read load.',
    themes: ['caching', 'infrastructure'],
    confidence: 'provisional',
    in_flight: true,
    metrics: [
      { name: 'read load reduction', value: '30%', status: 'unverified' },
    ],
    internal_references: [
      { type: 'linear', ref: 'AUTH-892' },
    ],
  };

  const retractedEntry: EvidenceEntry = {
    id: 'ev-003',
    date: '2026-03-01',
    company: 'acme-corp',
    title: 'Experimental Graph Query Engine',
    summary: 'Prototyped GraphQL federation layer.',
    impact: 'Rolled back due to memory overhead and schema synchronization limits.',
    themes: ['graphql', 'experimental'],
    confidence: 'retracted',
    in_flight: false,
    metrics: [],
    internal_references: [
      { type: 'linear', ref: 'ALERT-108' },
    ],
  };

  const unverifiedMetricEntry: EvidenceEntry = {
    id: 'ev-004',
    date: '2026-03-15',
    company: 'acme-corp',
    title: 'Async Event Pipeline',
    summary: 'Implemented Kafka consumer groups for notifications.',
    impact: 'Throughput increased significantly [METRIC NEEDED].',
    themes: ['events', 'streaming'],
    confidence: 'verified',
    in_flight: false,
    metrics: [
      { name: 'notification latency', value: '[METRIC NEEDED]', status: 'pending' },
    ],
    internal_references: [],
  };

  beforeEach(() => {
    store = new EvidenceStore();
    store.add(verifiedEntry, 'Verified entry narrative');
    store.add(provisionalEntry, 'Provisional entry narrative');
    store.add(retractedEntry, 'Retracted entry narrative');
    store.add(unverifiedMetricEntry, 'Unverified metric narrative');
  });

  describe('lintCitations', () => {
    it('returns isClean true and empty arrays when text contains no citations', () => {
      const text = 'Led engineering team delivering reliable cloud architecture.';
      const result = lintCitations(text, store);

      expect(result).toEqual({
        validCitations: [],
        danglingCitations: [],
        isClean: true,
      });
    });

    it('extracts valid citations wrapped in parentheses e.g. (ev-001)', () => {
      const text = 'Completed primary database migration (ev-001) successfully.';
      const result = lintCitations(text, store);

      expect(result.validCitations).toEqual(['ev-001']);
      expect(result.danglingCitations).toEqual([]);
      expect(result.isClean).toBe(true);
    });

    it('extracts valid citations without parentheses e.g. ev-001', () => {
      const text = 'Refer to evidence ev-001 and ev-002 for project background.';
      const result = lintCitations(text, store);

      expect(result.validCitations).toEqual(['ev-001', 'ev-002']);
      expect(result.danglingCitations).toEqual([]);
      expect(result.isClean).toBe(true);
    });

    it('identifies dangling citations not in EvidenceStore', () => {
      const text = 'Pioneered zero-knowledge auth protocol (ev-999).';
      const result = lintCitations(text, store);

      expect(result.validCitations).toEqual([]);
      expect(result.danglingCitations).toEqual(['ev-999']);
      expect(result.isClean).toBe(false);
    });

    it('handles mixed valid and dangling citations', () => {
      const text = 'Built migration engine (ev-001), experimental caching (ev-002), and missing item (ev-404).';
      const result = lintCitations(text, store);

      expect(result.validCitations).toEqual(['ev-001', 'ev-002']);
      expect(result.danglingCitations).toEqual(['ev-404']);
      expect(result.isClean).toBe(false);
    });

    it('deduplicates citations referenced multiple times', () => {
      const text = 'Database migration (ev-001) was crucial. Again, ev-001 resolved latency. Also missing ev-999 and (ev-999).';
      const result = lintCitations(text, store);

      expect(result.validCitations).toEqual(['ev-001']);
      expect(result.danglingCitations).toEqual(['ev-999']);
      expect(result.isClean).toBe(false);
    });

    it('matches citations case-insensitively and normalizes to lowercase', () => {
      const text = 'Referencing (EV-001) and EV-002.';
      const result = lintCitations(text, store);

      expect(result.validCitations).toEqual(['ev-001', 'ev-002']);
      expect(result.danglingCitations).toEqual([]);
      expect(result.isClean).toBe(true);
    });

    it('does not match non-citation tokens', () => {
      const text = 'Check dev-001, whatever-001, ev-12, ev-1234, and previous-ev-001.';
      const result = lintCitations(text, store);

      expect(result.validCitations).toEqual([]);
      expect(result.danglingCitations).toEqual([]);
      expect(result.isClean).toBe(true);
    });

    it('extracts multiple citations in a single parenthetical list', () => {
      const text = 'Combined architecture initiative (ev-001, ev-002).';
      const result = lintCitations(text, store);

      expect(result.validCitations).toEqual(['ev-001', 'ev-002']);
      expect(result.danglingCitations).toEqual([]);
      expect(result.isClean).toBe(true);
    });

    it('marks all citations as dangling when store is empty', () => {
      const emptyStore = new EvidenceStore();
      const text = 'Referencing (ev-001) in an empty store.';
      const result = lintCitations(text, emptyStore);

      expect(result.validCitations).toEqual([]);
      expect(result.danglingCitations).toEqual(['ev-001']);
      expect(result.isClean).toBe(false);
    });
  });

  describe('validateMetrics', () => {
    it('returns isClean true and empty issues for text without issues', () => {
      const text = 'Led project to improve system reliability (ev-001).';
      const result = validateMetrics(text, store);

      expect(result.isClean).toBe(true);
      expect(result.issues).toEqual([]);
    });

    it('detects explicit [METRIC NEEDED] tokens with line numbers', () => {
      const text = 'Line 1: High availability setup.\nLine 2: Reduced server costs by [METRIC NEEDED].';
      const result = validateMetrics(text);

      expect(result.isClean).toBe(false);
      expect(result.issues).toHaveLength(1);
      expect(result.issues[0]).toMatchObject({
        type: 'missing_metric',
        line: 2,
      });
      expect(result.issues[0].message).toContain('[METRIC NEEDED]');
    });

    it('detects multiple [METRIC NEEDED] tokens across multiple lines', () => {
      const text = '[METRIC NEEDED] on first line\nSecond line clean\n[METRIC NEEDED] on third line';
      const result = validateMetrics(text);

      expect(result.isClean).toBe(false);
      expect(result.issues).toHaveLength(2);
      expect(result.issues[0].line).toBe(1);
      expect(result.issues[1].line).toBe(3);
    });

    it('flags claims citing provisional evidence with provisional_evidence issue', () => {
      const text = 'Rolled out caching layer across clusters (ev-002).';
      const result = validateMetrics(text, store);

      expect(result.isClean).toBe(false);
      const provisionalIssue = result.issues.find((i) => i.type === 'provisional_evidence');
      expect(provisionalIssue).toBeDefined();
      expect(provisionalIssue?.line).toBe(1);
      expect(provisionalIssue?.message).toContain('ev-002');
    });

    it('flags claims citing retracted evidence with retracted_evidence issue', () => {
      const text = 'Evaluated graph query prototype (ev-003).';
      const result = validateMetrics(text, store);

      expect(result.isClean).toBe(false);
      const retractedIssue = result.issues.find((i) => i.type === 'retracted_evidence');
      expect(retractedIssue).toBeDefined();
      expect(retractedIssue?.line).toBe(1);
      expect(retractedIssue?.message).toContain('ev-003');
    });

    it('flags claims citing evidence entries that have unverified or pending metrics', () => {
      const text = 'Implemented async event pipeline (ev-004).';
      const result = validateMetrics(text, store);

      expect(result.isClean).toBe(false);
      const metricIssue = result.issues.find((i) => i.type === 'missing_metric');
      expect(metricIssue).toBeDefined();
      expect(metricIssue?.line).toBe(1);
      expect(metricIssue?.message).toContain('ev-004');
    });

    it('handles store without matching citation without crashing', () => {
      const text = 'Citing unknown evidence (ev-999).';
      const result = validateMetrics(text, store);

      expect(result.isClean).toBe(true);
      expect(result.issues).toEqual([]);
    });

    it('combines multiple issue types across multiple lines', () => {
      const text = [
        'Migrated database with 45% latency improvement (ev-001).',
        'Added Redis caching layer (ev-002).',
        'Shipped notifications with latency of [METRIC NEEDED].',
        'Tested GraphQL federation layer (ev-003).',
      ].join('\n');

      const result = validateMetrics(text, store);

      expect(result.isClean).toBe(false);
      expect(result.issues.some((i) => i.type === 'provisional_evidence' && i.line === 2)).toBe(true);
      expect(result.issues.some((i) => i.type === 'missing_metric' && i.line === 3)).toBe(true);
      expect(result.issues.some((i) => i.type === 'retracted_evidence' && i.line === 4)).toBe(true);
    });

    it('works correctly when store is omitted', () => {
      const text = 'Scalability improvements yielded [METRIC NEEDED] gains.';
      const result = validateMetrics(text);

      expect(result.isClean).toBe(false);
      expect(result.issues).toHaveLength(1);
      expect(result.issues[0].type).toBe('missing_metric');
    });

    it('ignores schema config lines and rule guideline quotes for [METRIC NEEDED]', () => {
      const text = [
        'metric_placeholder: "[METRIC NEEDED]"',
        '- For unmeasured latency, use the literal placeholder `[METRIC NEEDED]`.',
        '- No invented metrics — `[METRIC NEEDED]` is the placeholder, not an estimate.',
        'Production bullet with [METRIC NEEDED] latency reduction.',
      ].join('\n');
      const result = validateMetrics(text);

      expect(result.issues).toHaveLength(1);
      expect(result.issues[0].line).toBe(4);
    });

    it('validates citations with dynamic company prefixes (e.g. kong-001, dfn-001)', () => {
      const customStore = new EvidenceStore();
      customStore.add(
        {
          id: 'kong-001',
          date: '2023-01-01',
          company: 'Kong',
          title: 'Kong Gateway',
          summary: 'Summary',
          impact: 'Impact',
          themes: ['api-gateway'],
          confidence: 'provisional',
          in_flight: true,
          metrics: [],
          internal_references: [],
        },
        'Narrative'
      );

      const text = 'Authored plugin system (kong-001).';
      const result = validateMetrics(text, customStore);
      expect(result.issues).toHaveLength(1);
      expect(result.issues[0].type).toBe('provisional_evidence');
      expect(result.issues[0].message).toContain('kong-001');
    });
  });

  describe('redactText', () => {
    const defaultRules: PrivacyRulesConfig = {
      strip_patterns: ['AUTH-\\d+', 'ALERT-\\d+', 'DB-\\d+'],
      replacements: [
        { search: 'Fortune 50 Bank X', replace: 'a global tier-1 financial institution' },
        { search: 'Acme Corp', replace: 'a high-growth B2B SaaS platform' },
      ],
      banned_keywords: ['Project Titan', 'confidential', 'internal-only'],
    };

    it('returns unchanged text and isClean true when no rules match and no violations exist', () => {
      const text = 'Designed distributed database architecture for high availability.';
      const result = redactText(text, defaultRules);

      expect(result.redactedText).toBe(text);
      expect(result.violations).toEqual([]);
      expect(result.isClean).toBe(true);
    });

    it('strips citation tags like (ev-042) and normalizes spacing cleanly', () => {
      const text = 'Engineered token rotation protocol (ev-042) eliminating invalidations.';
      const result = redactText(text, defaultRules);

      expect(result.redactedText).toBe('Engineered token rotation protocol eliminating invalidations.');
      expect(result.violations).toEqual([]);
      expect(result.isClean).toBe(true);
    });

    it('strips citation tags at sentence boundaries without leaving spaces before punctuation', () => {
      const text = 'Architected zero-downtime database switch (ev-001).';
      const result = redactText(text, defaultRules);

      expect(result.redactedText).toBe('Architected zero-downtime database switch.');
      expect(result.isClean).toBe(true);
    });

    it('strips citation tags at the beginning of lines', () => {
      const text = '(ev-001) Led database migration across multiple availability zones.';
      const result = redactText(text, defaultRules);

      expect(result.redactedText).toBe('Led database migration across multiple availability zones.');
      expect(result.isClean).toBe(true);
    });

    it('strips citation tags without parentheses e.g. ev-001', () => {
      const text = 'Delivered under ev-001 for high reliability.';
      const result = redactText(text, defaultRules);

      expect(result.redactedText).toBe('Delivered under for high reliability.');
      expect(result.isClean).toBe(true);
    });

    it('strips ticket IDs according to strip_patterns', () => {
      const text = 'Resolved incident in AUTH-892 and verified via ALERT-108 in production.';
      const result = redactText(text, defaultRules);

      expect(result.redactedText).toBe('Resolved incident in and verified via in production.');
      expect(result.isClean).toBe(true);
    });

    it('strips parenthesized ticket IDs cleanly', () => {
      const text = 'Fixed session invalidation bug (AUTH-892) before customer launch.';
      const result = redactText(text, defaultRules);

      expect(result.redactedText).toBe('Fixed session invalidation bug before customer launch.');
      expect(result.isClean).toBe(true);
    });

    it('replaces confidential client or partner names using replacements dictionary', () => {
      const text = 'Deployed authentication system for Fortune 50 Bank X with 99.99% uptime.';
      const result = redactText(text, defaultRules);

      expect(result.redactedText).toBe('Deployed authentication system for a global tier-1 financial institution with 99.99% uptime.');
      expect(result.isClean).toBe(true);
    });

    it('handles case-insensitive replacements', () => {
      const text = 'Contracted with fortune 50 bank x on fraud detection.';
      const result = redactText(text, defaultRules);

      expect(result.redactedText).toBe('Contracted with a global tier-1 financial institution on fraud detection.');
      expect(result.isClean).toBe(true);
    });

    it('detects banned_keywords and includes them in violations with isClean false', () => {
      const text = 'Architected the core system under Project Titan with confidential specs.';
      const result = redactText(text, defaultRules);

      expect(result.isClean).toBe(false);
      expect(result.violations).toContain('Project Titan');
      expect(result.violations).toContain('confidential');
    });

    it('does not flag banned keywords if they were safely replaced by a replacement rule', () => {
      const customRules: PrivacyRulesConfig = {
        strip_patterns: [],
        replacements: [
          { search: 'Project Titan', replace: 'Platform Overhaul' },
        ],
        banned_keywords: ['Project Titan'],
      };

      const text = 'Lead engineer for Project Titan delivery.';
      const result = redactText(text, customRules);

      expect(result.redactedText).toBe('Lead engineer for Platform Overhaul delivery.');
      expect(result.violations).toEqual([]);
      expect(result.isClean).toBe(true);
    });

    it('handles multiline documents with combined stripping, replacement, and violations', () => {
      const multilineText = [
        '## Executive Summary (ev-001)',
        'Delivered scalable auth for Fortune 50 Bank X under ticket DB-101.',
        'This initiative contained confidential trade secrets.',
      ].join('\n');

      const result = redactText(multilineText, defaultRules);

      expect(result.redactedText).toContain('## Executive Summary');
      expect(result.redactedText).not.toContain('ev-001');
      expect(result.redactedText).toContain('a global tier-1 financial institution');
      expect(result.redactedText).not.toContain('DB-101');
      expect(result.violations).toEqual(['confidential']);
      expect(result.isClean).toBe(false);
    });
  });
});

import { PrivacyRulesConfig } from '../schemas/privacy.js';

export interface RedactResult {
  redactedText: string;
  violations: string[];
  isClean: boolean;
}

function escapeRegExp(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Normalizes horizontal whitespace, eliminates empty brackets/parens,
 * removes spaces before punctuation, and trims each line while preserving
 * multiline paragraph structures.
 */
function normalizeSpacing(text: string): string {
  return text
    .split('\n')
    .map((line) => {
      let cleaned = line
        // Remove empty parens or brackets like () or []
        .replace(/\(\s*\)/g, '')
        .replace(/\[\s*\]/g, '')
        // Collapse multiple horizontal whitespace characters into a single space
        .replace(/[ \t]+/g, ' ')
        // Remove space before punctuation: . , ; : ! ? ) ] }
        .replace(/ +([.,;:!?\)\]\}])/g, '$1')
        // Remove space after opening brackets: ( [ {
        .replace(/([\(\[\{]) +/g, '$1')
        // Trim leading and trailing whitespace on the line
        .trim();
      return cleaned;
    })
    .join('\n');
}

/**
 * Checks whether a keyword exists in text as an isolated token.
 */
function hasKeywordMatch(text: string, keyword: string): boolean {
  const escaped = escapeRegExp(keyword);
  const regex = new RegExp(`(?<![a-zA-Z0-9_-])${escaped}(?![a-zA-Z0-9_-])`, 'i');
  return regex.test(text);
}

/**
 * Redacts confidential details from text by:
 * 1. Stripping citation tags (e.g. (ev-042)) and normalizing spacing.
 * 2. Stripping ticket IDs according to strip_patterns.
 * 3. Replacing confidential entities using the replacements dictionary.
 * 4. Scanning the resulting text for banned_keywords violations.
 */
export interface RedactOptions {
  /**
   * Exact tokens (e.g. known evidence IDs like `ev-042`) that must survive redaction.
   * They are swapped for opaque sentinels before any stripping and restored afterwards,
   * so citation stripping and broad strip_patterns (e.g. `[A-Z]{2,10}-\d+`) cannot remove them.
   */
  protectTokens?: string[];
}

export function redactText(
  text: string,
  rules: PrivacyRulesConfig,
  options?: RedactOptions
): RedactResult {
  let currentText = text;

  const protectedTokens = Array.from(new Set((options?.protectTokens ?? []).filter(Boolean)))
    // Longest first so `ev-1000` is not partially captured by `ev-100`
    .sort((a, b) => b.length - a.length);
  if (protectedTokens.length > 0) {
    const alternation = protectedTokens.map(escapeRegExp).join('|');
    const tokenRegex = new RegExp(`(?<![a-zA-Z0-9_-])(${alternation})(?![a-zA-Z0-9_-])`, 'g');
    currentText = currentText.replace(tokenRegex, (match) => {
      return `⟦P${protectedTokens.indexOf(match)}⟧`;
    });
  }

  // 1. Strip internal citation tags (e.g. (ev-042), (ev-001, ev-002), [ev-042], ev-042, (kong-001), (dfn-001))
  currentText = currentText.replace(
    /(?:\s*\(|\s*\[)\s*(?:(?:ev|[a-z]{2,8})-[0-9]+)(?:\s*,\s*(?:(?:ev|[a-z]{2,8})-[0-9]+))*\s*(?:\)|\s*\])/gi,
    ''
  );
  currentText = currentText.replace(/(?<![a-zA-Z0-9_-])(?:ev|kong|dfn)-[0-9]+(?![a-zA-Z0-9_-])/gi, '');

  // 2. Strip internal ticket IDs according to strip_patterns
  const stripPatterns = rules.strip_patterns ?? [];
  for (const pattern of stripPatterns) {
    if (!pattern) continue;
    try {
      if (!pattern.includes('(') && !pattern.includes('[')) {
        const parenRegex = new RegExp(`(?:\\s*\\(|\\s*\\[)\\s*(?:${pattern})\\s*(?:\\)|\\s*\\])`, 'gi');
        currentText = currentText.replace(parenRegex, '');
      }
      const standaloneRegex = new RegExp(`(?<![a-zA-Z0-9_-])(?:${pattern})(?![a-zA-Z0-9])`, 'gi');
      currentText = currentText.replace(standaloneRegex, '');
    } catch {
      try {
        const fallbackRegex = new RegExp(pattern, 'gi');
        currentText = currentText.replace(fallbackRegex, '');
      } catch {
        // ignore invalid regex patterns
      }
    }
  }

  // 3. Replace confidential client/partner names or internal tools using replacements dictionary
  const replacements = rules.replacements ?? [];
  for (const rule of replacements) {
    if (!rule.search) continue;
    const escaped = escapeRegExp(rule.search);
    const regex = new RegExp(escaped, 'gi');
    currentText = currentText.replace(regex, () => rule.replace);
  }

  // Normalize whitespace and punctuation cleanly across lines
  currentText = normalizeSpacing(currentText);

  // 4. Scan for banned_keywords in the redacted text
  const bannedKeywords = rules.banned_keywords ?? [];
  const violations: string[] = [];
  const seenViolations = new Set<string>();

  for (const keyword of bannedKeywords) {
    if (!keyword || !keyword.trim()) continue;
    const trimmed = keyword.trim();
    if (hasKeywordMatch(currentText, trimmed)) {
      if (!seenViolations.has(trimmed)) {
        seenViolations.add(trimmed);
        violations.push(trimmed);
      }
    }
  }

  if (protectedTokens.length > 0) {
    currentText = currentText.replace(/⟦P(\d+)⟧/g, (_m, idx: string) => {
      return protectedTokens[Number(idx)] ?? '';
    });
  }

  return {
    redactedText: currentText,
    violations,
    isClean: violations.length === 0,
  };
}

import { EvidenceStore, hasMissingMetrics } from '../parsers/index-store.js';

export type MetricIssueType = 'missing_metric' | 'provisional_evidence' | 'retracted_evidence';

export interface MetricIssue {
  type: MetricIssueType;
  message: string;
  line?: number;
}

export interface MetricValidationResult {
  issues: MetricIssue[];
  isClean: boolean;
}

/**
 * Validates text claims for explicit missing metric tokens and cross-references
 * cited evidence entries to flag provisional, retracted, or unverified claims.
 */
export function validateMetrics(text: string, store?: EvidenceStore): MetricValidationResult {
  const issues: MetricIssue[] = [];
  const lines = text.split('\n');

  const prefixes = new Set<string>(['ev']);
  if (store) {
    for (const entry of store.getAll()) {
      const match = entry.id.match(/^([a-z0-9_-]+?)-[0-9]{3}$/i);
      if (match) {
        prefixes.add(match[1].toLowerCase());
      }
    }
  }
  const prefixPattern = Array.from(prefixes).map((p) => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
  const citationRegex = new RegExp(`(?<![a-zA-Z0-9_-])((?:${prefixPattern})-[0-9]{3})(?![a-zA-Z0-9_-])`, 'gi');
  const metricNeededRegex = /\[METRIC[\s_-]?NEEDED\]/i;

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const line = lines[i];

    // Detect explicit [METRIC NEEDED] tokens in claims
    // Ignore schema configuration lines (e.g. metric_placeholder: "[METRIC NEEDED]")
    // and rule guidelines that quote the placeholder as an instruction
    const isConfigLine = /^\s*metric_placeholder\s*:/i.test(line);
    const isGuidelineMeta = /use the literal (?:placeholder|string)|is the placeholder|replace `?\[METRIC/i.test(line);

    if (!isConfigLine && !isGuidelineMeta && metricNeededRegex.test(line)) {
      issues.push({
        type: 'missing_metric',
        message: `Line ${lineNum}: Explicit [METRIC NEEDED] token detected`,
        line: lineNum,
      });
    }

    // Check citations against store if store is provided
    if (store) {
      const lineCitations = Array.from(line.matchAll(citationRegex));
      const seenOnLine = new Set<string>();

      for (const match of lineCitations) {
        const rawId = match[1];
        const normalizedId = rawId.toLowerCase();

        if (seenOnLine.has(normalizedId)) {
          continue;
        }
        seenOnLine.add(normalizedId);

        const record = store.get(normalizedId) || store.get(rawId);
        if (!record) {
          continue;
        }

        if (record.confidence === 'provisional') {
          issues.push({
            type: 'provisional_evidence',
            message: `Line ${lineNum}: Claim cites provisional evidence ${record.id}`,
            line: lineNum,
          });
        } else if (record.confidence === 'retracted') {
          issues.push({
            type: 'retracted_evidence',
            message: `Line ${lineNum}: Claim cites retracted evidence ${record.id}`,
            line: lineNum,
          });
        }

        // Check for unverified or missing metrics
        const hasUnverified = record.metrics.some((m) => {
          const status = m.status.toLowerCase();
          return (
            status === 'unverified' ||
            status === 'pending' ||
            status === 'metric needed' ||
            status.includes('needed') ||
            m.value.includes('METRIC NEEDED') ||
            m.name.includes('METRIC NEEDED')
          );
        });

        if (hasUnverified || hasMissingMetrics(record.entry, record.narrative)) {
          issues.push({
            type: 'missing_metric',
            message: `Line ${lineNum}: Evidence ${record.id} contains unverified or missing metrics`,
            line: lineNum,
          });
        }
      }
    }
  }

  return {
    issues,
    isClean: issues.length === 0,
  };
}

import { EvidenceStore } from '../parsers/index-store.js';

export interface CitationLintResult {
  validCitations: string[];
  danglingCitations: string[];
  isClean: boolean;
}

/**
 * Lints citations in text against an EvidenceStore.
 * Extracts all (ev-[0-9]{3}) or ev-[0-9]{3} citations, resolves each
 * against the store, and flags any dangling citations.
 */
export function lintCitations(text: string, store: EvidenceStore): CitationLintResult {
  // Collect known citation prefixes from store (e.g. ev, kong, dfn)
  const knownPrefixes = new Set<string>(['ev', 'kong', 'dfn']);
  if (store && store.getAll) {
    for (const record of store.getAll()) {
      const parts = record.id.split('-');
      if (parts.length >= 2 && isNaN(Number(parts[0]))) {
        knownPrefixes.add(parts[0].toLowerCase());
      }
    }
  }

  const citationRegex = /(?<![a-zA-Z0-9_-])([a-z]{2,8}-[0-9]{3})(?![a-zA-Z0-9_-])/gi;
  const validCitations: string[] = [];
  const danglingCitations: string[] = [];
  const seenValid = new Set<string>();
  const seenDangling = new Set<string>();

  const matches = text.matchAll(citationRegex);
  for (const match of matches) {
    const rawId = match[1];
    const normalizedId = rawId.toLowerCase();
    const prefix = normalizedId.split('-')[0];

    // Only process as evidence citation if prefix matches known evidence prefix
    if (!knownPrefixes.has(prefix)) {
      continue;
    }

    if (store.has(normalizedId) || store.has(rawId)) {
      if (!seenValid.has(normalizedId)) {
        seenValid.add(normalizedId);
        validCitations.push(normalizedId);
      }
    } else {
      if (!seenDangling.has(normalizedId)) {
        seenDangling.add(normalizedId);
        danglingCitations.push(normalizedId);
      }
    }
  }

  return {
    validCitations,
    danglingCitations,
    isClean: danglingCitations.length === 0,
  };
}

export type SlopTellType =
  | 'hedge'
  | 'stakes'
  | 'delve'
  | 'bizjargon'
  | 'triadic'
  | 'copula'
  | 'corporate_uplift'
  | 'intensifier_filler'
  | 'assistant_voice'
  | 'vague_quantifier'
  | 'throat_clearing';

export interface SlopMatch {
  type: SlopTellType;
  patternName: string;
  matchedText: string;
  index: number;
  line?: number;
}

export interface SlopAuditResult {
  isClean: boolean;
  score: number; // 0 (clean) to 100+
  slopBand: 'clean' | 'low' | 'moderate' | 'high';
  matches: SlopMatch[];
  summary: string;
}

export interface SlopRule {
  type: SlopTellType;
  patternName: string;
  regex: RegExp;
  weight: number;
}

/**
 * Severity weights for each slop tell type.
 * Higher weight indicates stronger slop tell or corporate fluff.
 */
export const SLOP_WEIGHTS: Record<SlopTellType, number> = {
  corporate_uplift: 3,
  assistant_voice: 3,
  delve: 2,
  hedge: 2,
  stakes: 2,
  copula: 2,
  throat_clearing: 2,
  triadic: 2,
  bizjargon: 2,
  vague_quantifier: 1,
  intensifier_filler: 1,
};

/**
 * Comprehensive dictionary of slop detection rules.
 * Case-insensitive regular expressions targeting AI writing tells,
 * buzzword inflation, manufactured stakes, and empty hedging.
 */
export const SLOP_RULES: SlopRule[] = [
  {
    type: 'hedge',
    patternName: 'empty_hedging_stem',
    regex: /\b(?:it'?s|it is) (?:worth noting|important to (?:note|remember|understand))\b|\b(?:that said|needless to say|as we all know|at the end of the day)\b/gi,
    weight: SLOP_WEIGHTS.hedge,
  },
  {
    type: 'stakes',
    patternName: 'manufactured_stakes',
    regex: /\b(?:in today'?s (?:(?:fast-paced |digital |modern )+)?(?:world|landscape|era)|now more than ever|more important than ever|the stakes have never been higher)\b/gi,
    weight: SLOP_WEIGHTS.stakes,
  },
  {
    type: 'delve',
    patternName: 'llm_lexicon_filler',
    regex: /\b(?:delv(?:e|es|ed|ing)|tapestry|a testament to|(?:in )?the realm of|navigat(?:e|es|ed|ing) the (?:complex|intricat|nuanc))\b/gi,
    weight: SLOP_WEIGHTS.delve,
  },
  {
    type: 'bizjargon',
    patternName: 'business_jargon',
    regex: /\b(?:circle back|double down|move the needle|low-hanging fruit|boil the ocean|take a step back|on the same page|moving forward|lean into)\b/gi,
    weight: SLOP_WEIGHTS.bizjargon,
  },
  {
    type: 'triadic',
    patternName: 'triadic_buzzwords',
    regex: /\b(?:fast|reliable|scalable|secure|robust|powerful|flexible|intuitive|seamless|efficient|innovative|modern),?\s+(?:fast|reliable|scalable|secure|robust|powerful|flexible|intuitive|seamless|efficient|innovative|modern),?\s+and\s+(?:fast|reliable|scalable|secure|robust|powerful|flexible|intuitive|seamless|efficient|innovative|modern)\b/gi,
    weight: SLOP_WEIGHTS.triadic,
  },
  {
    type: 'copula',
    patternName: 'copula_inflation',
    regex: /\b(?:boasts|(?:serves|stands) as a (?:testament|reminder|symbol|cornerstone))\b/gi,
    weight: SLOP_WEIGHTS.copula,
  },
  {
    type: 'corporate_uplift',
    patternName: 'corporate_buzzword_salad',
    regex: /\b(?:spearhead(?:ed|ing)? cross[- ]functional synergies?|foster(?:ed|ing)? synergistic alignment|holistic paradigm shift|dr(?:ove|iving) best-in-class leverage)\b/gi,
    weight: SLOP_WEIGHTS.corporate_uplift,
  },
  {
    type: 'intensifier_filler',
    patternName: 'filler_intensifier',
    regex: /\b(?:truly|genuinely|honestly|literally|simply|basically|essentially|undoubtedly)\s+\w+/gi,
    weight: SLOP_WEIGHTS.intensifier_filler,
  },
  {
    type: 'assistant_voice',
    patternName: 'assistant_sycophancy',
    regex: /\b(?:great question|good question|i'?d be happy to|i'?m happy to|happy to help|as an ai(?: language model)?|i hope this (?:email|message) finds you well)\b/gi,
    weight: SLOP_WEIGHTS.assistant_voice,
  },
  {
    type: 'vague_quantifier',
    patternName: 'vague_quantifier',
    regex: /\b(?:a (?:wide|broad) (?:variety|range|array) of|a plethora of|a myriad of|a host of)\b/gi,
    weight: SLOP_WEIGHTS.vague_quantifier,
  },
  {
    type: 'throat_clearing',
    patternName: 'throat_clearing',
    regex: /\b(?:the uncomfortable truth is|it turns out(?:,| that)?|let me be clear|let that sink in|make no mistake)\b/gi,
    weight: SLOP_WEIGHTS.throat_clearing,
  },
];

/**
 * Calculates 1-based line number for a character index in text.
 */
function getLineNumber(text: string, index: number): number {
  let line = 1;
  for (let i = 0; i < index; i++) {
    if (text.charCodeAt(i) === 10) {
      line++;
    }
  }
  return line;
}

/**
 * Masks code blocks (```...```) and inline code spans (`...`) with spaces
 * to avoid matching keywords and code identifiers (e.g. `delve`) while
 * preserving exact string length, character indices, and line numbers.
 */
export function maskCodeSpans(text: string): string {
  let masked = text.replace(/(```[\s\S]*?```)/g, (match) => {
    return match.replace(/[^\r\n]/g, ' ');
  });
  masked = masked.replace(/(`[^`\r\n]+`)/g, (match) => {
    return match.replace(/[^\r\n]/g, ' ');
  });
  return masked;
}

/**
 * Scans text and returns all slop matches with line numbers and matched spans.
 */
export function detectSlop(text: string): SlopMatch[] {
  if (!text) return [];

  const rawMatches: SlopMatch[] = [];
  const scannableText = maskCodeSpans(text);

  for (const rule of SLOP_RULES) {
    const rx = new RegExp(rule.regex.source, rule.regex.flags);
    let match: RegExpExecArray | null;

    while ((match = rx.exec(scannableText)) !== null) {
      const matchedText = text.slice(match.index, match.index + match[0].length);
      const index = match.index;
      const line = getLineNumber(text, index);

      rawMatches.push({
        type: rule.type,
        patternName: rule.patternName,
        matchedText,
        index,
        line,
      });

      if (match.index === rx.lastIndex) {
        rx.lastIndex++;
      }
    }
  }

  // Sort by char index ascending, then by pattern name
  rawMatches.sort((a, b) => a.index - b.index || a.patternName.localeCompare(b.patternName));

  // Deduplicate exact duplicate matches at same index with same type
  const seen = new Set<string>();
  const matches: SlopMatch[] = [];
  for (const m of rawMatches) {
    const key = `${m.type}:${m.index}:${m.matchedText}`;
    if (!seen.has(key)) {
      seen.add(key);
      matches.push(m);
    }
  }

  return matches;
}

/**
 * Assigns weights to matches, calculates an aggregate slop score,
 * and categorizes the text into clean (0), low (1-2), moderate (3-5), or high (>5).
 */
export function auditSlop(text: string): SlopAuditResult {
  const matches = detectSlop(text);
  const score = matches.reduce((total, m) => total + (SLOP_WEIGHTS[m.type] ?? 1), 0);

  let slopBand: 'clean' | 'low' | 'moderate' | 'high';
  if (score === 0) {
    slopBand = 'clean';
  } else if (score <= 2) {
    slopBand = 'low';
  } else if (score <= 5) {
    slopBand = 'moderate';
  } else {
    slopBand = 'high';
  }

  const isClean = score === 0;
  let summary: string;
  if (isClean) {
    summary = 'Clean: No slop detected.';
  } else {
    const categories = Array.from(new Set(matches.map((m) => m.type)));
    summary = `Slop score ${score} (${slopBand}): detected ${matches.length} tell(s) across categories: ${categories.join(', ')}.`;
  }

  return {
    isClean,
    score,
    slopBand,
    matches,
    summary,
  };
}

const PROTECTED_CASING = [
  'iOS',
  'eBPF',
  'p99',
  'p95',
  'p90',
  'npm',
  'gRPC',
  'k8s',
  'kubectl',
  'eBay',
  'macOS',
  'iPhone',
  'iPad',
];

function safeCapitalizeFirstWord(str: string): string {
  if (!str) return str;
  const match = str.match(/^([a-zA-Z0-9_-]+)(.*)$/s);
  if (!match) return str;
  const firstWord = match[1];
  const rest = match[2];

  for (const protectedWord of PROTECTED_CASING) {
    if (firstWord.toLowerCase() === protectedWord.toLowerCase()) {
      return protectedWord + rest;
    }
  }
  return firstWord.charAt(0).toUpperCase() + firstWord.slice(1) + rest;
}

/**
 * Deterministically strips or tightens the most common empty hedging,
 * throat-clearing, and intensifier fillers without inventing facts or altering numbers/metrics.
 */
export function cleanSlop(text: string): { cleanedText: string; fixesApplied: string[] } {
  if (!text) {
    return { cleanedText: text, fixesApplied: [] };
  }

  const fixesApplied: string[] = [];
  const lines = text.split('\n');

  const leadingStemRules: Array<{ type: 'hedge' | 'throat'; regex: RegExp }> = [
    {
      type: 'hedge',
      regex: /^\s*(?:it'?s|it is) (?:worth noting|important to (?:note|remember|understand))(?: that)?(?:[:,])?\s*/i,
    },
    {
      type: 'hedge',
      regex: /^\s*(?:that said|needless to say|as we all know|at the end of the day)(?:[:,])?\s*/i,
    },
    {
      type: 'throat',
      regex: /^\s*(?:the uncomfortable truth is(?: that)?|it turns out(?: that|,)?|let me be clear|let that sink in|make no mistake)(?:[:,])?\s*/i,
    },
  ];

  const cleanedLines = lines.map((line) => {
    // Preserve bullet point, number, or leading whitespace indentation
    const prefixMatch = line.match(/^(\s*(?:[-*•]|\d+[.)])\s*|\s*)/);
    const prefix = prefixMatch ? prefixMatch[1] : '';
    let content = line.slice(prefix.length);

    if (content.trim().length === 0) {
      return line;
    }

    // 1. Strip leading hedge and throat-clearing stems at start of line content
    let matchedLeading = true;
    let loopGuard = 0;
    while (matchedLeading && loopGuard < 5) {
      matchedLeading = false;
      loopGuard++;

      for (const rule of leadingStemRules) {
        const match = content.match(rule.regex);
        if (match && match[0].length > 0) {
          const stem = match[0];
          content = safeCapitalizeFirstWord(content.slice(stem.length));
          if (rule.type === 'hedge') {
            fixesApplied.push(`Stripped empty hedge: "${stem.trim()}"`);
          } else {
            fixesApplied.push(`Stripped throat-clearing: "${stem.trim()}"`);
          }
          matchedLeading = true;
          break;
        }
      }
    }

    // 2. Strip hedge and throat-clearing stems after sentence boundaries (. ! ?)
    const sentenceStemRegex = /(?<=[.!?]\s+)(?:((?:it'?s|it is) (?:worth noting|important to (?:note|remember|understand))(?: that)?(?:[:,])?\s*)|((?:that said|needless to say|as we all know|at the end of the day)(?:[:,])?\s*)|((?:the uncomfortable truth is(?: that)?|it turns out(?: that|,)?|let me be clear|let that sink in|make no mistake)(?:[:,])?\s*))(\S+)/gi;
    content = content.replace(
      sentenceStemRegex,
      (_match, hedge1, hedge2, throat, firstWord) => {
        const hedge = hedge1 || hedge2;
        if (hedge) {
          fixesApplied.push(`Stripped empty hedge: "${hedge.trim()}"`);
        } else if (throat) {
          fixesApplied.push(`Stripped throat-clearing: "${throat.trim()}"`);
        }
        return safeCapitalizeFirstWord(firstWord);
      }
    );

    // 3. Strip leading intensifier fillers at start of line content
    const leadingIntensifierMatch = content.match(
      /^(truly|genuinely|honestly|literally|simply|basically|essentially|undoubtedly)[,:]?\s*(\S+)/i
    );
    if (leadingIntensifierMatch) {
      const word = leadingIntensifierMatch[1];
      const nextWord = leadingIntensifierMatch[2];
      fixesApplied.push(`Removed intensifier filler: "${word}"`);
      content = safeCapitalizeFirstWord(nextWord) + content.slice(leadingIntensifierMatch[0].length);
    }

    // 4. Strip intensifiers after sentence boundaries
    const sentenceIntensifierRegex = /(?<=[.!?]\s+)(truly|genuinely|honestly|literally|simply|basically|essentially|undoubtedly)[,:]?\s*(\S+)/gi;
    content = content.replace(sentenceIntensifierRegex, (_match, word, firstWord) => {
      fixesApplied.push(`Removed intensifier filler: "${word}"`);
      return safeCapitalizeFirstWord(firstWord);
    });

    // 5. Strip mid-sentence filler intensifier adverbs modifying adjacent words
    const midIntensifierRegex = /\b(truly|genuinely|honestly|literally|simply|basically|essentially|undoubtedly)[,]?\s+(?=\S)/gi;
    content = content.replace(midIntensifierRegex, (_match, word) => {
      fixesApplied.push(`Removed intensifier filler: "${word}"`);
      return '';
    });

    // Normalize multiple spaces created by removals
    content = content.replace(/[ \t]{2,}/g, ' ');

    return prefix + content;
  });

  return {
    cleanedText: cleanedLines.join('\n'),
    fixesApplied,
  };
}

